from abc import ABC, abstractmethod
from typing import List, Any

# 1. Abstract class with template method
class SortAlgorithm(ABC):
    def __init__(self, data: List[Any]):
        self.data = data

    def sort(self):
        n = len(self.data)
        # Sorting skeleton: actual algorithm defined in subclasses
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(j, j + 1):
                    self.swap(j, j + 1)

    @abstractmethod
    def compare(self, index1: int, index2: int) -> bool:
        """Compare two elements decided by indices; return True if swap needed."""
        pass

    @abstractmethod
    def swap(self, index1: int, index2: int):
        """Swap two elements at specified indices."""
        pass

# 2. BubbleSort implementation
class BubbleSort(SortAlgorithm):
    def compare(self, index1: int, index2: int) -> bool:
        return self.data[index1] > self.data[index2]

    def swap(self, index1: int, index2: int):
        self.data[index1], self.data[index2] = self.data[index2], self.data[index1]

# 2. SelectionSort implementation
class SelectionSort(SortAlgorithm):
    def compare(self, index1: int, index2: int) -> bool:
        # In selection sort, comparison is used to find the minimum element
        min_index = index1
        for j in range(index1 + 1, len(self.data)):
            if self.data[j] < self.data[min_index]:
                min_index = j
        if min_index != index1:
            self.swap(index1, min_index)
        return False  # Since swap handled here, returning False to avoid extra swaps

    def swap(self, index1: int, index2: int):
        self.data[index1], self.data[index2] = self.data[index2], self.data[index1]

# 4. Testing
if __name__ == "__main__":
    array1 = [64, 34, 25, 12, 22, 11, 90]
    bubble_sorter = BubbleSort(array1)
    bubble_sorter.sort()
    print(f"BubbleSort result: {bubble_sorter.data}")

    array2 = ["banana", "apple", "cherry", "date"]
    selection_sorter = SelectionSort(array2)
    selection_sorter.sort()
    print(f"SelectionSort result: {selection_sorter.data}")
